corrected_code:
package handlers

import (
	"encoding/json"
	"net/http"

	"github.com/gorilla/mux"
	"myapp/auth"
	"myapp/fleet"
)

type TelemetryHandler struct {
	FleetClient fleet.Client
}

func (th *TelemetryHandler) GetVehicleTelemetry(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	vehicleID := vars["vehicleId"]
	operator := auth.GetOperator(r.Context())

	telemetry, err := th.FleetClient.FetchTelemetryForFleet(r.Context(), vehicleID, operator.FleetOrgID)
	if err != nil {
		http.Error(w, "Vehicle telemetry unavailable or access forbidden", http.StatusForbidden)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(telemetry)
}
